function depthSource(pack,file){return '<details class="full-code"><summary>展开完整源码 · '+file+'</summary>'+code(file,file.endsWith('.py')?'PYTHON':'TEXT',continuousDepthFiles[pack][file])+'</details>';}
function depthRun(pack,file,anchor,command){return '<h3 id="'+anchor+'" class="walkthrough-run">运行 '+file+'</h3>'+code('解压实验包，在文件所在目录执行','BASH',command)+'<p><a href="/labs/'+pack+'.zip" download>下载完整实验包 ↓</a> · <a href="/labs/'+pack+'/'+file+'" download>下载源码 ↓</a> · <a href="/labs/'+pack+'/validation.json">查看执行记录与源码摘要 →</a></p>'+depthSource(pack,file);}
chapter('platform','A3.9','speculative-decoding','推测解码：从接受概率到批量验证与缓存回退',
 '小模型先提议，大模型并行核对。用三个词元算清为什么不改分布，再用实际CPU注意力检查位置、接受前缀与KV缓存。',
 '先读Transformer、Attention、模型推理服务；知道概率之和为1，以及KV缓存保存过去位置的键和值。',
 ['采样：手算接受与拒绝的概率质量','执行：对齐并行验证的位置与缓存','判断：分开正确性、调用次数和真实速度'],[
 ['先分清谁提议，谁决定最终分布',
 para('语言模型根据已经生成的词元预测下一个词元。词元（token）是分词器使用的编号单位，不一定对应一个汉字。已经确定的编号序列叫前缀。自回归生成每确定一个新编号，就把它加入前缀，下一步的预测条件也随之改变。',
 '目标模型是我们希望保持输出行为的模型，记它对下一词元的概率为p。草稿模型是较便宜的提议者，记概率为q。推测解码先让草稿模型连续提出k个候选，再让目标模型一次核对这些候选经过的前缀。最终只提交从开头连续通过的部分，遇到第一个拒绝就修正；后面基于错误前缀计算的候选不能直接留下。',
 '本章区分两种输出规则。贪心解码每步选择概率最大的词元，平分时还需固定破平规则；随机采样则按概率抽取。贪心可以逐项核对编号相等，随机采样要求保持整个输出分布，同一个随机种子下的逐字结果未必相同。下面先证明随机情形，最后用贪心夹具观察真实缓存。')+
 table(['对象','负责什么','不能据此推出'],[['草稿q','给出候选及其条件概率','候选可直接当目标结果'],['目标p','核对同一前缀下的分布','一次调用成本与单词元相同'],['接受前缀','连续通过验证的候选','后面候选也可保留'],['KV缓存','保存已处理位置的键和值','被拒绝位置仍属于当前序列']])],
 ['先只提议一个词元：算清留下多少概率',
 para('用只有A、B、C三个词元的词表做手算。目标p=[1/2,1/3,1/6]，草稿q=[1/6,1/3,1/2]。这里把分配到某个词元的概率份额称为概率质量，例如草稿分给A的是1/6。先按q抽一个候选y，再以min(1,p(y)/q(y))的概率接受。A与B总被接受，C只有1/3的接受概率：草稿把太多概率放在C上，需要退回多余部分。')+
 knowledgeFormula('候选被接受的概率质量','q(y) × min(1, p(y)/q(y)) = min(p(y), q(y))','候选必须实际来自q。q(y)=0的位置不会被提议，不在这个位置计算0作为分母的比值。')+
 table(['词元','目标p','草稿q','接受概率','留下的质量'],[['A','1/2','1/6','1','1/6'],['B','1/3','1/3','1','1/3'],['C','1/6','1/2','1/3','1/6']])+
 para('留下的总质量是2/3，也就是这一步的平均接受率。目标还缺A的1/3，其他两个位置已经够了。若拒绝后又直接按p重新抽，便给B和C补上本来不缺的质量；这不是一个只影响效率的小改动，而是改变了输出分布。')+
 figure('v48-spec-probability-mass','上半部逐项比较p/q；下半部把留下的2/3与拒绝后补回的1/3拼回目标p。所有数值由Fraction精确核对。')],
 ['拒绝以后，从哪里补回缺少的部分',
 para('残差分布指拒绝后用于补回不足质量的分布。先逐项取max(p−q,0)，再除以它们的总和。本例未归一化的残差为[1/3,0,0]，归一化后为[1,0,0]，因此拒绝时一定补A。最终得到[1/6+1/3,1/3,1/6]=p。')+
 knowledgeFormula('拒绝分支补齐剩余质量','r(y)=max(p(y)−q(y),0) / Σₓ max(p(x)−q(x),0)','两个分布的和都是1，因此“草稿多给的总量”等于“目标缺少的总量”。没有拒绝质量时直接接受，不构造分母为0的残差。')+
 para('错误对照把拒绝后的分布写成p，会得到[1/3,4/9,2/9]，与目标[1/2,1/3,1/6]不同。直接交出草稿则得到q，同样不对。程序用有理数保存这些分数，避免把小数舍入误差或有限次数采样波动当成正确性结论。',
 '这里的p和q都必须是实际采样规则处理后的分布。例如温度会缩放分数，Top-k只保留概率最高的若干位置，再归一化。若候选来自处理后的q，却拿处理前的q算接受率，证明前提已经不成立。两模型还要对齐词表编号与所条件的完整前缀；不同分词方式不能直接把编号当成同一个事件。')+
 code('单位置核心；空残差只在不存在拒绝时出现','PYTHON','accepted = [min(a, b) for a, b in zip(p, q)]\nreject_mass = 1 - sum(accepted)\nif reject_mass == 0:\n    return accepted\nresidual = normalize([max(0, a - b) for a, b in zip(p, q)])\nreturn [a + reject_mass * r for a, r in zip(accepted, residual)]')],
 ['多个候选怎样用一次目标调用核对',
 para('设已有前缀为P，草稿顺序提出d₁、d₂、d₃。q₁条件是P，q₂条件是P+d₁，q₃条件是P+d₁+d₂；它们不是在同一个分布里独立抽三次。目标也要给出对应的p₁、p₂、p₃，并提供完整草稿前缀之后的p₄。',
 '因果注意力只允许当前位置读取自己和更早的位置。草稿已经给出了候选内容，目标可以在一次前向计算中同时处理这些位置，再用因果掩码限制可见范围。计算并行不等于最终输出无依赖：接受仍从左到右判断，第二个拒绝后，第三个候选所依赖的前缀不再成立。')+
 figure('v48-spec-verification-grid','已有前缀的最后一个分数预测d₁；把三个候选送入目标后，三个输出分别预测下一位置。矩阵显示允许读取的前缀，避免把分数错移一格。')+
 para('若前三个都接受，再从p₄抽一个额外词元，一轮最多提交k+1个。若第二个拒绝，只保留d₁，从该位置的残差补一个词元，本轮提交两个。此处的“额外词元”不是免费增加的模型能力；它来自最后一个候选位置已经计算出的下一词元分布。',
 '精确程序把k固定为2，词表仍为3，并让p/q随最后一个词元循环变换。它枚举全部草稿、接受/拒绝分支和补偿结果，多轮生成长度3的序列；27条完整序列的概率逐项等于普通目标采样的条件概率乘积。只比较单词元频率会漏掉前缀处理错误，完整序列对照可以检查这层关系。')+
 depthRun('speculative-decoding','exact_sampling.py','spec-exact-run','python3 -B exact_sampling.py')],
 ['缓存回退，要删掉哪些位置',
 para('KV缓存存的是注意力计算中每个历史位置的键K和值V。已有前缀长度n，核对k个草稿后，临时缓存长n+k；最终只接受前a个候选，就只能保留前n+a个位置，然后把修正词元送入目标，缓存才变成n+a+1。分数选对了却保留错误位置，下一步仍会沿错误上下文继续计算。')+
 figure('v48-spec-cache-cut','实际夹具：前缀[1,2,3]，草稿[0,5,3]。接受0后拒绝5，临时缓存6行裁到4行，再消费修正4得到5行。错误方案保留7行，下一步分数也发生变化。')+
 para('本例先用目标的贪心结果构造可控草稿[0,4,3]，再故意把第二个改成5，得到[0,5,3]。这份草稿是验证夹具，不能用来测独立小模型的真实接受率。正确输出[0,4]与逐词目标基线一致；回退后的K、V和下一步分数也逐项相等。',
 '错误对照不裁临时缓存，直接追加修正4，长度从6变7，而正确长度应为5。实际CPU模型的下一步分数最大绝对差约0.450285。长度错已足以判失败，数值差进一步展示了错误会继续传播。真实系统还要同步回退草稿缓存、位置编号和采样状态；分页缓存要回收或解除对应块引用，不能只在界面上缩短文本。')+
 code('裁剪发生在消费修正词元之前','PYTHON','keep = len(prefix) + accepted\ntrimmed = tuple(x[:keep].clone() for x in speculative_cache)\nnext_logits, committed_cache = model.forward([correction], trimmed)')],
 ['实际CPU模型怎样验证并行位置没有算错',
 para('第二个程序实际调用PyTorch 2.5.1，在CPU上执行一个未训练、单层、单注意力头的因果模型，词表8、隐藏宽度8，使用float64。输入包含词元嵌入与绝对位置向量；每次前向都真正生成K/V张量，并与过去缓存拼接。它没有把“缓存”简化成一个长度整数。带旧缓存时，当前查询的绝对位置从n开始，允许读取的键位置应小于等于n+i；直接套一个从左上角开始的非方阵三角掩码，会让新位置看不到应有历史。',
 '程序对每个验证位置另跑一次完整前缀，比较批量验证的条件分数；再把最终提交序列逐词喂给目标，比较输出编号、缓存内容及下一步分数，误差阈值为10⁻¹²。全部接受时，提交[0,4,3,0]，最终缓存7行；第二个拒绝时提交[0,4]，最终5行。')+
 table(['判据','全部接受','第二个拒绝'],[['草稿','[0,4,3]','[0,5,3]'],['连续接受数','3','1'],['提交输出','[0,4,3,0]','[0,4]'],['临时→裁后→提交缓存','6→6→7','6→4→5'],['同提交范围的目标调用','2次，对照4次','2次，对照2次']])+
 para('调用数从共同的预填充完成以后开始计，两边都把新输出全部消费进缓存，便于公平比较下一步状态。推测方案包含一次批量验证和一次消费修正/额外词元；串行对照逐个消费同一段输出。这里统计的是模型函数调用，不是GPU内核数量，更不是加速倍数。')+
 depthRun('speculative-decoding','cache_verify.py','spec-cache-run','python3.12 -m venv .venv\n.venv/bin/pip install torch==2.5.1\n.venv/bin/python -B cache_verify.py')],
 ['接受率为什么不能直接换算成加速比',
 para('一次验证多个位置会增加计算和缓存工作；草稿本身也花时间。批量验证如果更好地摊薄目标模型权重读取，可能比多次单词元解码便宜，但这取决于模型、批次、硬件和负载。目标已经处于大批次高利用率时，额外草稿与验证也可能得不偿失。',
 '在一个简化成本模型中，若每个位置以相同且相互独立的概率α通过，k个草稿的期望提交数为1+α+…+αᵏ。设一次草稿候选成本为c，一轮验证及必要状态推进成本为v，普通目标每词元成本为t，则理想比较是(kc+v)/(1+α+…+αᵏ)与t。α=2/3、k=2时，期望数为19/9，仍需知道分子成本才能判断快慢。',
 '这些独立、同分布假设并不描述所有真实文本；接受率会随前缀、任务和模型变化。实验中的受控草稿不能代入生产成本模型。调大k也会增加显存、验证工作和拒绝浪费，应按端到端延迟、输出长度、批次分布和吞吐共同选取。')+
 figure('v48-spec-cost-boundary','这是声明的成本算例：α=2/3、k=2，期望提交19/9；标出草稿与验证成本后才能比较。图不是CPU或GPU计时。')],
 ['放进服务系统，还要处理哪些边界',
 para('客户端只应看到已经通过的词元。若先流式发送草稿，再在拒绝后撤回，常见文本接口无法保证客户端回滚。结束词元也只能在接受或修正提交后决定停止；长度上限应按最终提交数截断，不能因一轮多出词元就越过用户限制。',
 '两个模型需要各自的权重与缓存。高并发下应把草稿成本、目标验证批次、显存占用和排队时间合起来测；单条请求少几次目标调用，未必改善整个服务的P99延迟。取消请求还应终止未完成工作并回收两边的状态，不能只把HTTP连接关闭。',
 '迁移到真实框架时，先固定目标模型、分词器、温度、截断与停止规则，再验证无草稿基线和推测结果的正确性，之后测性能。贪心逐词相等与随机分布正确使用不同判据；有限采样统计只能提供经验检验，不能替代算法证明。')+
 linkTo('inference-performance','继续设计端到端性能测量')],
 ['把结果和能证明的范围对齐',
 para('本章给出的两层证据互补：Fraction程序证明一个有限前缀依赖系统中的完整采样分布；实际CPU模型验证批量分数、词元位置与真实K/V张量回退。前者没有模型性能，后者没有训练好的独立草稿模型，也没有执行随机采样算法。二者不能拼接成“某大模型GPU加速已验证”。',
 '练习时先把拒绝后的残差换成p，指出哪三个概率发生变化；再去掉缓存裁剪，观察长度和下一步分数；最后提出一个需要真实GPU才能回答的问题，例如相同并发和长度分布下，草稿开销是否抵消目标调用节省。把不同问题交给对应证据，才能解释优化何时值得用。')]
 ],['推测解码的接受率达到2/3，是否意味着一定快1.5倍？第二个候选拒绝后能否保留后面的缓存？','不能。接受率还需结合草稿、验证、缓存与排队成本；本例没有GPU性能测量。拒绝后只保留已接受前缀的缓存，再消费修正词元，后面基于错误前缀的K/V必须回退。'],['specPaper','specFraction','specTorch'],['transformer-model','attention-mechanics','model-serving','inference-performance']);
